import { APP_NAME } from '@artifact-hub/shared';
import { PlusIcon } from 'lucide-react';
import { Link, Outlet } from 'react-router';
import { Button } from '@/components/ui/button.tsx';
import { PublishDialog } from '@/features/artifacts/publish-dialog.tsx';
import { useCurrentUser } from '@/features/auth/use-auth.ts';
import { UserMenu } from './user-menu.tsx';

/** Layout of every signed-in page. Rendered inside `RequireAuth`, so the user is known. */
export function AppShell() {
  const { data: user } = useCurrentUser();

  return (
    <div className="flex min-h-svh flex-col">
      <header className="border-b">
        <div className="mx-auto flex h-14 w-full max-w-6xl items-center justify-between px-4">
          <Link to="/" className="font-semibold tracking-tight">
            {APP_NAME}
          </Link>
          <div className="flex items-center gap-2">
            <PublishDialog>
              <Button size="sm">
                <PlusIcon aria-hidden="true" />
                Publish
              </Button>
            </PublishDialog>
            {user ? <UserMenu user={user} /> : null}
          </div>
        </div>
      </header>
      <main className="mx-auto w-full max-w-6xl flex-1 px-4 py-8">
        <Outlet />
      </main>
    </div>
  );
}
import type { User } from '@artifact-hub/shared';
import { LogOutIcon, SettingsIcon } from 'lucide-react';
import { Link } from 'react-router';
import { toast } from 'sonner';
import { Avatar, AvatarFallback } from '@/components/ui/avatar.tsx';
import { Button } from '@/components/ui/button.tsx';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu.tsx';
import { useLogout } from '@/features/auth/use-auth.ts';
import { describeError } from '@/lib/api/api-error.ts';

function initials(name: string): string {
  const parts = name.trim().split(/\s+/);
  const letters = parts.length > 1 ? [parts[0], parts.at(-1)] : [parts[0]];
  return letters
    .map((part) => part?.[0] ?? '')
    .join('')
    .toUpperCase();
}

export function UserMenu({ user }: { user: User }) {
  const logout = useLogout();

  // After logout the signed-in user is cleared, and the protected route redirects to login.
  const onLogout = () =>
    logout.mutate(undefined, {
      onError: (error) => toast.error(`Couldn't log out. ${describeError(error)}`),
    });

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" className="h-9 gap-2 px-2" aria-label="Account menu">
          <Avatar className="size-7">
            <AvatarFallback className="text-xs">{initials(user.displayName)}</AvatarFallback>
          </Avatar>
          <span className="hidden max-w-40 truncate text-sm sm:inline">{user.displayName}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-56">
        <DropdownMenuLabel className="font-normal">
          <div className="truncate text-sm font-medium">{user.displayName}</div>
          <div className="truncate text-xs text-muted-foreground">{user.email}</div>
        </DropdownMenuLabel>
        <DropdownMenuSeparator />
        <DropdownMenuItem asChild>
          <Link to="/settings">
            <SettingsIcon />
            Settings
          </Link>
        </DropdownMenuItem>
        <DropdownMenuItem onSelect={onLogout} disabled={logout.isPending}>
          <LogOutIcon />
          Log out
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
import type { RouteObject } from 'react-router';
import { AppShell } from '@/components/app-shell.tsx';
import { GuestOnly, RequireAuth } from '@/components/route-guards.tsx';
import { ArtifactPage } from './artifact-page.tsx';
import { GalleryPage } from './gallery-page.tsx';
import { LoginPage } from './login-page.tsx';
import { NotFoundPage } from './not-found-page.tsx';
import { SettingsPage } from './settings-page.tsx';
import { SharedLinkPage } from './shared-link-page.tsx';
import { SignupPage } from './signup-page.tsx';
import { UploadPage } from './upload-page.tsx';

/** Everything requires a session except login, signup and share links. */
export const routes: RouteObject[] = [
  // Works signed in or not: share links are for people without an account too.
  { path: '/s/:token', element: <SharedLinkPage /> },
  {
    element: <GuestOnly />,
    children: [
      { path: '/login', element: <LoginPage /> },
      { path: '/signup', element: <SignupPage /> },
    ],
  },
  {
    element: <RequireAuth />,
    children: [
      {
        element: <AppShell />,
        children: [
          { index: true, element: <GalleryPage /> },
          { path: 'artifacts/:id', element: <ArtifactPage /> },
          { path: 'settings', element: <SettingsPage /> },
          { path: 'upload/:token', element: <UploadPage /> },
          { path: '*', element: <NotFoundPage /> },
        ],
      },
    ],
  },
];
import {
  ARTIFACT_LIST_DEFAULT_PAGE_SIZE,
  ARTIFACT_LIST_SCOPES,
  type ArtifactListScope,
  artifactListQuerySchema,
} from '@artifact-hub/shared';
import { Loader2Icon, PlusIcon } from 'lucide-react';
import { Link, useNavigate, useSearchParams } from 'react-router';
import type { z } from 'zod';
import { Pagination } from '@/components/pagination.tsx';
import { Button } from '@/components/ui/button.tsx';
import { ArtifactCard } from '@/features/artifacts/artifact-card.tsx';
import type { GalleryFilters as Filters } from '@/features/artifacts/artifacts.types.ts';
import { GalleryFilters, hasFilters } from '@/features/artifacts/gallery-filters.tsx';
import { PublishDialog } from '@/features/artifacts/publish-dialog.tsx';
import { useArtifactList } from '@/features/artifacts/use-artifacts.ts';
import { InlineError, InlineLoading } from '@/components/inline-status.tsx';
import { cn } from '@/lib/utils';

const SCOPES: Record<ArtifactListScope, { tab: string; heading: string }> = {
  mine: { tab: 'Mine', heading: 'My artifacts' },
  shared: { tab: 'Shared with me', heading: 'Shared with me' },
  public: { tab: 'Company', heading: 'Shared with the company' },
};

/** The gallery's URL state; anything invalid falls back to its default. */
function useGalleryParams(): Filters & { page: number } {
  const [searchParams] = useSearchParams();
  const parse = <T,>(schema: z.ZodType<T>, key: string): T | undefined => {
    const parsed = schema.safeParse(searchParams.get(key) ?? undefined);
    return parsed.success ? parsed.data : undefined;
  };
  const { shape } = artifactListQuerySchema;
  const scopeParam = searchParams.get('scope');
  const scope = ARTIFACT_LIST_SCOPES.find((s) => s === scopeParam) ?? 'mine';
  const page = Number(searchParams.get('page'));
  return {
    scope,
    q: parse(shape.q, 'q'),
    type: parse(shape.type, 'type'),
    tag: parse(shape.tag, 'tag'),
    owner: parse(shape.owner, 'owner'),
    updatedFrom: parse(shape.updatedFrom, 'updatedFrom'),
    updatedTo: parse(shape.updatedTo, 'updatedTo'),
    page: Number.isInteger(page) && page >= 1 ? page : 1,
  };
}

/** The gallery URL for these filters and page, leaving defaults out. */
function galleryHref(
  { scope, q, type, tag, owner, updatedFrom, updatedTo }: Filters,
  page = 1,
): string {
  const query = new URLSearchParams();
  if (scope !== 'mine') query.set('scope', scope);
  for (const [key, value] of Object.entries({ q, type, tag, owner, updatedFrom, updatedTo })) {
    if (value) query.set(key, value);
  }
  if (page > 1) query.set('page', String(page));
  const search = query.toString();
  return search ? `/?${search}` : '/';
}

/**
 * Home: my artifacts, those shared with me, or those shared with the whole company; searched
 * and filtered.
 */
export function GalleryPage() {
  const { page, ...filters } = useGalleryParams();
  const { scope } = filters;
  const navigate = useNavigate();
  const pageSize = ARTIFACT_LIST_DEFAULT_PAGE_SIZE;
  const { data, error, refetch, isPlaceholderData } = useArtifactList({
    ...filters,
    page,
    pageSize,
  });
  const filtered = hasFilters(filters);
  // New filters start from the first page, without piling up history while typing.
  const applyFilters = (next: Filters) => void navigate(galleryHref(next), { replace: true });

  return (
    <section className="grid gap-6">
      <nav aria-label="Gallery" className="flex gap-1 border-b">
        {ARTIFACT_LIST_SCOPES.map((s) => (
          <Link
            key={s}
            to={galleryHref({ scope: s })}
            aria-current={s === scope ? 'page' : undefined}
            className={cn(
              '-mb-px border-b-2 px-3 py-2 text-sm font-medium transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-none',
              s === scope
                ? 'border-primary text-foreground'
                : 'border-transparent text-muted-foreground hover:text-foreground',
            )}
          >
            {SCOPES[s].tab}
          </Link>
        ))}
      </nav>

      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <h1 className="text-2xl font-semibold tracking-tight">{SCOPES[scope].heading}</h1>
        {isPlaceholderData ? (
          <p role="status" className="flex items-center gap-1.5 text-sm text-muted-foreground">
            <Loader2Icon className="size-4 animate-spin" aria-hidden="true" />
            {filtered ? 'Searching…' : 'Loading…'}
          </p>
        ) : data && data.total > 0 ? (
          <p className="text-sm text-muted-foreground">
            {data.total} {data.total === 1 ? 'artifact' : 'artifacts'}
          </p>
        ) : null}
      </div>

      <GalleryFilters
        key={scope}
        filters={filters}
        loading={isPlaceholderData}
        onChange={applyFilters}
      />

      {error ? (
        <div className="h-64">
          <InlineError error={error} onRetry={() => void refetch()} />
        </div>
      ) : !data ? (
        <div className="h-64">
          <InlineLoading />
        </div>
      ) : data.total === 0 && filtered ? (
        <div className="flex flex-col items-center gap-3 rounded-xl border border-dashed py-16 text-center">
          <h2 className="text-lg font-medium">No artifacts match</h2>
          <p className="max-w-sm text-sm text-muted-foreground">
            Try other words, or fewer filters.
          </p>
          <Button variant="outline" onClick={() => applyFilters({ scope })}>
            Clear filters
          </Button>
        </div>
      ) : data.total === 0 ? (
        <EmptyGallery scope={scope} />
      ) : data.items.length === 0 ? (
        <p className="py-16 text-center text-muted-foreground">
          There's nothing on this page.{' '}
          <Link to={galleryHref(filters)} className="underline">
            Go to the first page
          </Link>
        </p>
      ) : (
        <>
          <ul
            className={cn(
              'grid gap-4 transition-opacity sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4',
              // Earlier results stay while new ones load, faded.
              isPlaceholderData && 'opacity-50',
            )}
            aria-busy={isPlaceholderData}
          >
            {data.items.map((artifact) => (
              <li key={artifact.id} className="grid">
                <ArtifactCard artifact={artifact} />
              </li>
            ))}
          </ul>
          <Pagination
            page={page}
            pageCount={Math.ceil(data.total / pageSize)}
            hrefFor={(n) => galleryHref(filters, n)}
          />
        </>
      )}
    </section>
  );
}

const EMPTY_SHARED: Record<Exclude<ArtifactListScope, 'mine'>, { title: string; text: string }> = {
  shared: {
    title: 'Nothing shared with you yet',
    text: 'Artifacts colleagues share with you by name show up here.',
  },
  public: {
    title: 'Nothing shared with the company yet',
    text: 'Artifacts shared with everyone at the company show up here, for all to view and comment on.',
  },
};

function EmptyGallery({ scope }: { scope: ArtifactListScope }) {
  if (scope !== 'mine') {
    const { title, text } = EMPTY_SHARED[scope];
    return (
      <div className="flex flex-col items-center gap-2 rounded-xl border border-dashed py-16 text-center">
        <h2 className="text-lg font-medium">{title}</h2>
        <p className="max-w-sm text-sm text-muted-foreground">{text}</p>
      </div>
    );
  }
  return (
    <div className="flex flex-col items-center gap-4 rounded-xl border border-dashed py-16 text-center">
      <h2 className="text-lg font-medium">Nothing published yet</h2>
      <p className="max-w-sm text-sm text-muted-foreground">
        Publish HTML, SVG, Markdown, an image or a PDF to view it here, keep versions and share it.
      </p>
      <PublishDialog>
        <Button>
          <PlusIcon aria-hidden="true" />
          Publish your first artifact
        </Button>
      </PublishDialog>
    </div>
  );
}
import { ARTIFACT_TYPE_FILTERS, type ArtifactTypeFilter } from '@artifact-hub/shared';
import { Loader2Icon, SearchIcon, XIcon } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { Button } from '@/components/ui/button.tsx';
import { Input } from '@/components/ui/input.tsx';
import { NativeSelect } from '@/components/ui/native-select.tsx';
import { useAppConfig } from '@/features/config/use-app-config.ts';
import { formatUpdatedRange } from '@/lib/format.ts';
import { TYPE_FILTER_LABELS } from './artifact-types.ts';
import type { GalleryFilters as Filters } from './artifacts.types.ts';
import { AiSearchDialog } from './ai-search-dialog.tsx';
import { useArtifactTags } from './use-artifacts.ts';

const TYPE_FILTERS = Object.keys(ARTIFACT_TYPE_FILTERS) as ArtifactTypeFilter[];
const SEARCH_DELAY_MS = 300;

/** Whether `filters` narrow their scope at all. */
export function hasFilters({ q, type, tag, owner, updatedFrom, updatedTo }: Filters): boolean {
  return Boolean(q || type || tag || owner || updatedFrom || updatedTo);
}

/**
 * Search box, type and tag filters for a gallery scope. A search applies once typing pauses,
 * the other filters at once (Enter applies a search at once too); every change goes through
 * `onChange` (which puts it in the URL). With AI, *AI search* replaces the filters with what a
 * description asks for; owner and dates show as removable chips.
 */
export function GalleryFilters({
  filters,
  loading,
  onChange,
}: {
  filters: Filters;
  /** Results for the current filters are on their way. */
  loading: boolean;
  onChange: (filters: Filters) => void;
}) {
  const [text, setText] = useState(filters.q ?? '');
  /** A search typed but not applied yet. */
  const [pending, setPending] = useState(false);
  const [shownQ, setShownQ] = useState(filters.q);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const { data: tags } = useArtifactTags(filters.scope);
  const { data: config } = useAppConfig();
  const smart = config?.features.ai ?? false;

  // The URL's search changed elsewhere (Clear filters, the back button): show it.
  if (filters.q !== shownQ) {
    setShownQ(filters.q);
    if (text.trim() !== (filters.q ?? '')) setText(filters.q ?? '');
  }
  useEffect(() => () => clearTimeout(timer.current), []);

  /** Applies `changes` with whatever is typed, cancelling a search still waiting to apply. */
  const apply = (changes: Partial<Filters>, typed = text) => {
    clearTimeout(timer.current);
    setPending(false);
    onChange({ ...filters, q: typed.trim() || undefined, ...changes });
  };

  const onType = (value: string) => {
    setText(value);
    setPending(true);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => apply({}, value), SEARCH_DELAY_MS);
  };

  /** Filters from an AI search, replacing the current ones. */
  const applySearch = (found: Filters) => {
    clearTimeout(timer.current);
    setPending(false);
    setText(found.q ?? '');
    onChange(found);
  };

  const active = hasFilters(filters);
  const updated = formatUpdatedRange(filters.updatedFrom, filters.updatedTo);
  const chips = [
    filters.owner ? { label: `By ${filters.owner}`, clear: { owner: undefined } } : null,
    updated ? { label: updated, clear: { updatedFrom: undefined, updatedTo: undefined } } : null,
  ].filter((chip) => chip !== null);
  const tagOptions = tags?.map((item) => item.tag) ?? [];
  // A tag from the URL stays selectable even if it isn't among the most used.
  if (filters.tag && !tagOptions.includes(filters.tag)) tagOptions.unshift(filters.tag);

  return (
    <div role="search" className="flex flex-wrap items-center gap-2">
      <div className="relative min-w-56 flex-1">
        {pending || loading ? (
          <Loader2Icon
            className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 animate-spin text-muted-foreground"
            aria-hidden="true"
          />
        ) : (
          <SearchIcon
            className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground"
            aria-hidden="true"
          />
        )}
        <Input
          type="search"
          aria-label="Search"
          placeholder="Search titles, tags and descriptions"
          className="pl-8"
          value={text}
          onChange={(event) => onType(event.target.value)}
          onKeyDown={(event) => {
            if (event.key !== 'Enter' || event.nativeEvent.isComposing) return;
            event.preventDefault();
            apply({});
          }}
        />
      </div>
      {smart ? <AiSearchDialog scope={filters.scope} onSearch={applySearch} /> : null}
      <NativeSelect
        aria-label="Type"
        value={filters.type ?? ''}
        onChange={(event) => apply({ type: (event.target.value || undefined) as Filters['type'] })}
      >
        <option value="">All types</option>
        {TYPE_FILTERS.map((type) => (
          <option key={type} value={type}>
            {TYPE_FILTER_LABELS[type]}
          </option>
        ))}
      </NativeSelect>
      <NativeSelect
        aria-label="Tag"
        value={filters.tag ?? ''}
        onChange={(event) => apply({ tag: event.target.value || undefined })}
      >
        <option value="">All tags</option>
        {tagOptions.map((tag) => (
          <option key={tag} value={tag}>
            {tag}
          </option>
        ))}
      </NativeSelect>
      {chips.map(({ label, clear }) => (
        <Button
          key={label}
          variant="secondary"
          size="sm"
          aria-label={`Remove filter: ${label}`}
          onClick={() => apply(clear)}
        >
          {label}
          <XIcon aria-hidden="true" />
        </Button>
      ))}
      {active ? (
        <Button
          variant="ghost"
          onClick={() => {
            clearTimeout(timer.current);
            setPending(false);
            setText('');
            onChange({ scope: filters.scope });
          }}
        >
          <XIcon aria-hidden="true" />
          Clear filters
        </Button>
      ) : null}
    </div>
  );
}
import type {
  Artifact,
  ArtifactListScope,
  CreateArtifactRequest,
  CreateVersionRequest,
  UpdateArtifactRequest,
} from '@artifact-hub/shared';
import { keepPreviousData, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { isApiError } from '@/lib/api/api-error.ts';
import { submissionKey } from '@/lib/api/submission-key.ts';
import { retryTransient } from '@/lib/query-client.ts';
import {
  artifactListQueryKey,
  artifactListsQueryKey,
  artifactQueryKey,
  artifactTagsQueryKey,
  artifactVersionsQueryKey,
  deleteArtifact,
  fetchArtifact,
  fetchArtifacts,
  fetchArtifactTags,
  fetchArtifactVersions,
  interpretSearch,
  publishArtifact,
  publishVersion,
  updateArtifact,
} from './artifacts-api.ts';
import type { ArtifactListParams } from './artifacts.types.ts';

export function useArtifact(id: string) {
  return useQuery({
    queryKey: artifactQueryKey(id),
    queryFn: ({ signal }) => fetchArtifact(id, signal),
    // A 404 won't change by asking again.
    retry: (failureCount, error) => !isApiError(error, 'NOT_FOUND') && failureCount < 2,
  });
}

export function useArtifactList(params: ArtifactListParams) {
  return useQuery({
    queryKey: artifactListQueryKey(params),
    queryFn: ({ signal }) => fetchArtifacts(params, signal),
    // Keep showing the current page while the next one loads.
    placeholderData: keepPreviousData,
  });
}

/** Turns a search typed in plain language into gallery filters (never fails because of AI). */
export function useInterpretSearch() {
  return useMutation({
    mutationFn: ({ q, scope }: { q: string; scope: ArtifactListScope }) =>
      interpretSearch(q, scope),
  });
}

/** Invalidated with the lists, since publishing or editing changes them. */
export function useArtifactTags(scope: ArtifactListScope) {
  return useQuery({
    queryKey: artifactTagsQueryKey(scope),
    queryFn: ({ signal }) => fetchArtifactTags(scope, signal),
  });
}

export function usePublishArtifact() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (variables: { file: File; metadata: CreateArtifactRequest }) =>
      publishArtifact(variables.file, variables.metadata, submissionKey(variables)),
    retry: retryTransient,
    onSuccess: (artifact) => {
      queryClient.setQueryData(artifactQueryKey(artifact.id), artifact);
      void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
    },
  });
}

export function useArtifactVersions(id: string, { enabled = true } = {}) {
  return useQuery({
    queryKey: artifactVersionsQueryKey(id),
    queryFn: ({ signal }) => fetchArtifactVersions(id, signal),
    enabled,
  });
}

/** Caches a changed artifact and refreshes everything that shows it. */
function useArtifactChanged() {
  const queryClient = useQueryClient();
  return (artifact: Artifact) => {
    queryClient.setQueryData(artifactQueryKey(artifact.id), artifact);
    void queryClient.invalidateQueries({ queryKey: artifactVersionsQueryKey(artifact.id) });
    void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
  };
}

export function usePublishVersion(id: string) {
  const onChanged = useArtifactChanged();
  return useMutation({
    mutationFn: (variables: { file: File; metadata: CreateVersionRequest }) =>
      publishVersion(id, variables.file, variables.metadata, submissionKey(variables)),
    retry: retryTransient,
    onSuccess: onChanged,
  });
}

export function useUpdateArtifact(id: string) {
  const onChanged = useArtifactChanged();
  return useMutation({
    mutationFn: (changes: UpdateArtifactRequest) => updateArtifact(id, changes),
    onSuccess: onChanged,
  });
}

/**
 * `leavePage` navigates away from the artifact; its queries are dropped only after that, so
 * the page doesn't refetch the artifact and flash "not found" on its way out.
 */
export function useDeleteArtifact(id: string, leavePage: () => void | Promise<void>) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: () => deleteArtifact(id),
    onSuccess: async () => {
      await leavePage();
      queryClient.removeQueries({ queryKey: artifactQueryKey(id) });
      void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
    },
  });
}
import {
  type Artifact,
  type ArtifactListResponse,
  type ArtifactListScope,
  type ArtifactTagListResponse,
  artifactTagListResponseSchema,
  type ArtifactVersion,
  artifactListResponseSchema,
  artifactResponseSchema,
  artifactVersionListResponseSchema,
  type CreateArtifactRequest,
  type CreateVersionRequest,
  type SearchInterpretation,
  searchInterpretationSchema,
  type UpdateArtifactRequest,
} from '@artifact-hub/shared';
import { apiFetchContent, apiRequest } from '@/lib/api/client.ts';
import type { ArtifactListParams } from './artifacts.types.ts';

/**
 * One artifact: `['artifact', id]`, its versions under it (invalidating the artifact refreshes
 * both). Lists: `['artifacts', params]`, invalidated together.
 */
export const artifactQueryKey = (id: string) => ['artifact', id] as const;
export const artifactVersionsQueryKey = (id: string) =>
  [...artifactQueryKey(id), 'versions'] as const;
export const artifactListsQueryKey = ['artifacts'] as const;
export const artifactListQueryKey = (params: ArtifactListParams) =>
  [...artifactListsQueryKey, params] as const;

export async function fetchArtifacts(
  { scope, page, pageSize, ...filters }: ArtifactListParams,
  signal?: AbortSignal,
): Promise<ArtifactListResponse> {
  const query = new URLSearchParams({ scope, page: String(page), pageSize: String(pageSize) });
  for (const [key, value] of Object.entries(filters)) {
    if (value) query.set(key, value);
  }
  return apiRequest(`/artifacts?${query}`, { schema: artifactListResponseSchema, signal });
}

/**
 * Gallery filters for a search typed in plain language. Without AI, or when it fails, a plain
 * search for the text in the same scope (`interpreted: false`).
 */
export async function interpretSearch(
  q: string,
  scope: ArtifactListScope,
): Promise<SearchInterpretation> {
  const query = new URLSearchParams({ q, scope });
  return apiRequest(`/search/interpret?${query}`, { schema: searchInterpretationSchema });
}

export const artifactTagsQueryKey = (scope: ArtifactListScope) =>
  [...artifactListsQueryKey, 'tags', scope] as const;

/** The tags used in a gallery scope, the most used first. */
export async function fetchArtifactTags(
  scope: ArtifactListScope,
  signal?: AbortSignal,
): Promise<ArtifactTagListResponse['items']> {
  const query = new URLSearchParams({ scope });
  return (
    await apiRequest(`/artifacts/tags?${query}`, { schema: artifactTagListResponseSchema, signal })
  ).items;
}

/**
 * Multipart upload: the metadata first, then the file (the server reads them in that order).
 * With the same `idempotencyKey`, a retry returns the artifact the first attempt published.
 */
export async function publishArtifact(
  file: File,
  metadata: CreateArtifactRequest,
  idempotencyKey?: string,
): Promise<Artifact> {
  const form = new FormData();
  form.append('metadata', JSON.stringify(metadata));
  form.append('file', file);
  return (
    await apiRequest('/artifacts', {
      method: 'POST',
      body: form,
      schema: artifactResponseSchema,
      idempotencyKey,
    })
  ).artifact;
}

export async function fetchArtifact(id: string, signal?: AbortSignal): Promise<Artifact> {
  return (
    await apiRequest(artifactPath(id), {
      schema: artifactResponseSchema,
      signal,
    })
  ).artifact;
}

const artifactPath = (id: string) => `/artifacts/${encodeURIComponent(id)}`;

