374	/**
375	 * Search box, type and tag filters for a gallery scope. A search applies once typing pauses,
376	 * the other filters at once (Enter applies a search at once too); every change goes through
377	 * `onChange` (which puts it in the URL). With AI, *AI search* replaces the filters with what a
378	 * description asks for; owner and dates show as removable chips.
379	 */
380	export function GalleryFilters({
381	  filters,
382	  loading,
383	  onChange,
384	}: {
385	  filters: Filters;
386	  /** Results for the current filters are on their way. */
387	  loading: boolean;
388	  onChange: (filters: Filters) => void;
389	}) {
390	  const [text, setText] = useState(filters.q ?? '');
391	  /** A search typed but not applied yet. */
392	  const [pending, setPending] = useState(false);
393	  const [shownQ, setShownQ] = useState(filters.q);
394	  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
395	  const { data: tags } = useArtifactTags(filters.scope);
396	  const { data: config } = useAppConfig();
397	  const smart = config?.features.ai ?? false;
398	
399	  // The URL's search changed elsewhere (Clear filters, the back button): show it.
400	  if (filters.q !== shownQ) {
401	    setShownQ(filters.q);
402	    if (text.trim() !== (filters.q ?? '')) setText(filters.q ?? '');
403	  }
404	  useEffect(() => () => clearTimeout(timer.current), []);
405	
406	  /** Applies `changes` with whatever is typed, cancelling a search still waiting to apply. */
407	  const apply = (changes: Partial<Filters>, typed = text) => {
408	    clearTimeout(timer.current);
409	    setPending(false);
410	    onChange({ ...filters, q: typed.trim() || undefined, ...changes });
411	  };
412	
413	  const onType = (value: string) => {
414	    setText(value);
415	    setPending(true);
416	    clearTimeout(timer.current);
417	    timer.current = setTimeout(() => apply({}, value), SEARCH_DELAY_MS);
418	  };
419	
420	  /** Filters from an AI search, replacing the current ones. */
421	  const applySearch = (found: Filters) => {
422	    clearTimeout(timer.current);
423	    setPending(false);
424	    setText(found.q ?? '');
425	    onChange(found);
426	  };
427	
428	  const active = hasFilters(filters);
429	  const updated = formatUpdatedRange(filters.updatedFrom, filters.updatedTo);
430	  const chips = [
431	    filters.owner ? { label: `By ${filters.owner}`, clear: { owner: undefined } } : null,
432	    updated ? { label: updated, clear: { updatedFrom: undefined, updatedTo: undefined } } : null,
433	  ].filter((chip) => chip !== null);
434	  const tagOptions = tags?.map((item) => item.tag) ?? [];
435	  // A tag from the URL stays selectable even if it isn't among the most used.
436	  if (filters.tag && !tagOptions.includes(filters.tag)) tagOptions.unshift(filters.tag);
437	
438	  return (
439	    <div role="search" className="flex flex-wrap items-center gap-2">
440	      <div className="relative min-w-56 flex-1">
441	        {pending || loading ? (
442	          <Loader2Icon
443	            className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 animate-spin text-muted-foreground"
444	            aria-hidden="true"
445	          />
446	        ) : (
447	          <SearchIcon
448	            className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground"
449	            aria-hidden="true"
450	          />
451	        )}
452	        <Input
453	          type="search"
454	          aria-label="Search"
455	          placeholder="Search titles, tags and descriptions"
456	          className="pl-8"
457	          value={text}
458	          onChange={(event) => onType(event.target.value)}
459	          onKeyDown={(event) => {
460	            if (event.key !== 'Enter' || event.nativeEvent.isComposing) return;
461	            event.preventDefault();
462	            apply({});
463	          }}
464	        />
465	      </div>
466	      {smart ? <AiSearchDialog scope={filters.scope} onSearch={applySearch} /> : null}
467	      <NativeSelect
468	        aria-label="Type"
469	        value={filters.type ?? ''}
470	        onChange={(event) => apply({ type: (event.target.value || undefined) as Filters['type'] })}
471	      >
472	        <option value="">All types</option>
473	        {TYPE_FILTERS.map((type) => (
474	          <option key={type} value={type}>
475	            {TYPE_FILTER_LABELS[type]}
476	          </option>
477	        ))}
478	      </NativeSelect>
479	      <NativeSelect
480	        aria-label="Tag"
481	        value={filters.tag ?? ''}
482	        onChange={(event) => apply({ tag: event.target.value || undefined })}
483	      >
484	        <option value="">All tags</option>
485	        {tagOptions.map((tag) => (
486	          <option key={tag} value={tag}>
487	            {tag}
488	          </option>
489	        ))}
490	      </NativeSelect>
491	      {chips.map(({ label, clear }) => (
492	        <Button
493	          key={label}
494	          variant="secondary"
495	          size="sm"
496	          aria-label={`Remove filter: ${label}`}
497	          onClick={() => apply(clear)}
498	        >
499	          {label}
500	          <XIcon aria-hidden="true" />
501	        </Button>
502	      ))}
503	      {active ? (
504	        <Button
505	          variant="ghost"
506	          onClick={() => {
507	            clearTimeout(timer.current);
508	            setPending(false);
509	            setText('');
510	            onChange({ scope: filters.scope });
511	          }}
512	        >
513	          <XIcon aria-hidden="true" />
514	          Clear filters
515	        </Button>
516	      ) : null}
517	    </div>
518	  );
519	}
