539	  fetchArtifacts,
540	  fetchArtifactTags,
541	  fetchArtifactVersions,
542	  interpretSearch,
543	  publishArtifact,
544	  publishVersion,
545	  updateArtifact,
546	} from './artifacts-api.ts';
547	import type { ArtifactListParams } from './artifacts.types.ts';
548	
549	export function useArtifact(id: string) {
550	  return useQuery({
551	    queryKey: artifactQueryKey(id),
552	    queryFn: ({ signal }) => fetchArtifact(id, signal),
553	    // A 404 won't change by asking again.
554	    retry: (failureCount, error) => !isApiError(error, 'NOT_FOUND') && failureCount < 2,
555	  });
556	}
557	
558	export function useArtifactList(params: ArtifactListParams) {
559	  return useQuery({
560	    queryKey: artifactListQueryKey(params),
561	    queryFn: ({ signal }) => fetchArtifacts(params, signal),
562	    // Keep showing the current page while the next one loads.
563	    placeholderData: keepPreviousData,
564	  });
565	}
566	
567	/** Turns a search typed in plain language into gallery filters (never fails because of AI). */
568	export function useInterpretSearch() {
569	  return useMutation({
570	    mutationFn: ({ q, scope }: { q: string; scope: ArtifactListScope }) =>
571	      interpretSearch(q, scope),
572	  });
573	}
574	
575	/** Invalidated with the lists, since publishing or editing changes them. */
576	export function useArtifactTags(scope: ArtifactListScope) {
577	  return useQuery({
578	    queryKey: artifactTagsQueryKey(scope),
579	    queryFn: ({ signal }) => fetchArtifactTags(scope, signal),
580	  });
581	}
582	
583	export function usePublishArtifact() {
584	  const queryClient = useQueryClient();
585	  return useMutation({
586	    mutationFn: (variables: { file: File; metadata: CreateArtifactRequest }) =>
587	      publishArtifact(variables.file, variables.metadata, submissionKey(variables)),
588	    retry: retryTransient,
589	    onSuccess: (artifact) => {
590	      queryClient.setQueryData(artifactQueryKey(artifact.id), artifact);
591	      void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
592	    },
593	  });
594	}
595	
596	export function useArtifactVersions(id: string, { enabled = true } = {}) {
597	  return useQuery({
598	    queryKey: artifactVersionsQueryKey(id),
599	    queryFn: ({ signal }) => fetchArtifactVersions(id, signal),
600	    enabled,
601	  });
602	}
603	
604	/** Caches a changed artifact and refreshes everything that shows it. */
605	function useArtifactChanged() {
606	  const queryClient = useQueryClient();
607	  return (artifact: Artifact) => {
608	    queryClient.setQueryData(artifactQueryKey(artifact.id), artifact);
609	    void queryClient.invalidateQueries({ queryKey: artifactVersionsQueryKey(artifact.id) });
610	    void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
611	  };
612	}
613	
614	export function usePublishVersion(id: string) {
615	  const onChanged = useArtifactChanged();
616	  return useMutation({
617	    mutationFn: (variables: { file: File; metadata: CreateVersionRequest }) =>
618	      publishVersion(id, variables.file, variables.metadata, submissionKey(variables)),
619	    retry: retryTransient,
620	    onSuccess: onChanged,
621	  });
622	}
623	
624	export function useUpdateArtifact(id: string) {
625	  const onChanged = useArtifactChanged();
626	  return useMutation({
627	    mutationFn: (changes: UpdateArtifactRequest) => updateArtifact(id, changes),
628	    onSuccess: onChanged,
629	  });
630	}
631	
632	/**
633	 * `leavePage` navigates away from the artifact; its queries are dropped only after that, so
634	 * the page doesn't refetch the artifact and flash "not found" on its way out.
635	 */
636	export function useDeleteArtifact(id: string, leavePage: () => void | Promise<void>) {
637	  const queryClient = useQueryClient();
638	  return useMutation({
639	    mutationFn: () => deleteArtifact(id),
640	    onSuccess: async () => {
641	      await leavePage();
642	      queryClient.removeQueries({ queryKey: artifactQueryKey(id) });
643	      void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
644	    },
645	  });
646	}
