666	/**
667	 * One artifact: `['artifact', id]`, its versions under it (invalidating the artifact refreshes
668	 * both). Lists: `['artifacts', params]`, invalidated together.
669	 */
670	export const artifactQueryKey = (id: string) => ['artifact', id] as const;
671	export const artifactVersionsQueryKey = (id: string) =>
672	  [...artifactQueryKey(id), 'versions'] as const;
673	export const artifactListsQueryKey = ['artifacts'] as const;
674	export const artifactListQueryKey = (params: ArtifactListParams) =>
675	  [...artifactListsQueryKey, params] as const;
