677	export async function fetchArtifacts(
678	  { scope, page, pageSize, ...filters }: ArtifactListParams,
679	  signal?: AbortSignal,
680	): Promise<ArtifactListResponse> {
681	  const query = new URLSearchParams({ scope, page: String(page), pageSize: String(pageSize) });
682	  for (const [key, value] of Object.entries(filters)) {
683	    if (value) query.set(key, value);
684	  }
685	  return apiRequest(`/artifacts?${query}`, { schema: artifactListResponseSchema, signal });
686	}
687	
688	/**
689	 * Gallery filters for a search typed in plain language. Without AI, or when it fails, a plain
690	 * search for the text in the same scope (`interpreted: false`).
691	 */
692	export async function interpretSearch(
693	  q: string,
694	  scope: ArtifactListScope,
695	): Promise<SearchInterpretation> {
696	  const query = new URLSearchParams({ q, scope });
697	  return apiRequest(`/search/interpret?${query}`, { schema: searchInterpretationSchema });
698	}
699	
700	export const artifactTagsQueryKey = (scope: ArtifactListScope) =>
701	  [...artifactListsQueryKey, 'tags', scope] as const;
702	
703	/** The tags used in a gallery scope, the most used first. */
704	export async function fetchArtifactTags(
705	  scope: ArtifactListScope,
706	  signal?: AbortSignal,
707	): Promise<ArtifactTagListResponse['items']> {
708	  const query = new URLSearchParams({ scope });
709	  return (
710	    await apiRequest(`/artifacts/tags?${query}`, { schema: artifactTagListResponseSchema, signal })
711	  ).items;
712	}
713	
714	/**
715	 * Multipart upload: the metadata first, then the file (the server reads them in that order).
716	 * With the same `idempotencyKey`, a retry returns the artifact the first attempt published.
717	 */
718	export async function publishArtifact(
719	  file: File,
720	  metadata: CreateArtifactRequest,
721	  idempotencyKey?: string,
722	): Promise<Artifact> {
723	  const form = new FormData();
724	  form.append('metadata', JSON.stringify(metadata));
725	  form.append('file', file);
726	  return (
727	    await apiRequest('/artifacts', {
728	      method: 'POST',
729	      body: form,
730	      schema: artifactResponseSchema,
731	      idempotencyKey,
732	    })
733	  ).artifact;
734	}
735	
736	export async function fetchArtifact(id: string, signal?: AbortSignal): Promise<Artifact> {
737	  return (
738	    await apiRequest(artifactPath(id), {
739	      schema: artifactResponseSchema,
740	      signal,
741	    })
742	  ).artifact;
743	}
744	
745	const artifactPath = (id: string) => `/artifacts/${encodeURIComponent(id)}`;
746	
747	/** Multipart, like publishing: the details first, then the file. Returns the updated artifact. */
748	export async function publishVersion(
749	  id: string,
750	  file: File,
751	  metadata: CreateVersionRequest,
752	  idempotencyKey?: string,
753	): Promise<Artifact> {
754	  const form = new FormData();
755	  form.append('metadata', JSON.stringify(metadata));
756	  form.append('file', file);
757	  return (
758	    await apiRequest(`${artifactPath(id)}/versions`, {
759	      method: 'POST',
760	      body: form,
761	      schema: artifactResponseSchema,
762	      idempotencyKey,
763	    })
764	  ).artifact;
765	}
766	
767	/** Every version, newest first. */
768	export async function fetchArtifactVersions(
