778	}
779	
780	export async function updateArtifact(
781	  id: string,
782	  changes: UpdateArtifactRequest,
783	): Promise<Artifact> {
784	  return (
785	    await apiRequest(artifactPath(id), {
786	      method: 'PATCH',
787	      body: changes,
788	      schema: artifactResponseSchema,
789	    })
790	  ).artifact;
791	}
792	
793	export async function deleteArtifact(id: string): Promise<void> {
794	  await apiRequest(artifactPath(id), { method: 'DELETE' });
795	}
796	
797	/** Where a version's bytes are, relative to `/api`. */
798	export function artifactContentPath(artifactId: string, versionNo: number): string {
799	  return `${artifactPath(artifactId)}/versions/${versionNo}/content`;
800	}
801	
802	/** URL of a version's bytes, for `<img>`, `<iframe>` and download links. */
803	export function artifactContentUrl(
804	  artifactId: string,
805	  versionNo: number,
806	  { download = false } = {},
807	): string {
