816	/** Content (at a path relative to `/api`) as bytes, e.g. a PDF. */
817	export async function fetchContentBytes(
818	  contentPath: string,
819	  signal?: AbortSignal,
820	): Promise<Uint8Array> {
821	  const res = await apiFetchContent(contentPath, { signal });
822	  return new Uint8Array(await res.arrayBuffer());
823	}
824	import type { ArtifactListScope, ArtifactTypeFilter } from '@artifact-hub/shared';
825	import type { z } from 'zod';
