import {
  ARTIFACT_LIST_SCOPES,
  ARTIFACT_TYPE_FILTERS,
  type ArtifactListSort,
  type ArtifactTypeFilter,
} from '@artifact-hub/shared';
import { Loader2Icon, SearchIcon, XIcon } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { Button } from '@/components/ui/button.tsx';
import { Input } from '@/components/ui/input.tsx';
import { NativeSelect } from '@/components/ui/native-select.tsx';
import { useAppConfig } from '@/features/config/use-app-config.ts';
import { formatUpdatedRange } from '@/lib/format.ts';
import { SCOPE_LABELS, TYPE_FILTER_LABELS } from './artifact-types.ts';
import type { GalleryFilters as Filters } from './artifacts.types.ts';
import { AiSearchDialog } from './ai-search-dialog.tsx';
import { useArtifactTags } from './use-artifacts.ts';

const TYPE_FILTERS = Object.keys(ARTIFACT_TYPE_FILTERS) as ArtifactTypeFilter[];
const SEARCH_DELAY_MS = 300;
const SORT_LABELS: Record<ArtifactListSort | 'relevance', string> = {
  relevance: 'Best match',
  newest: 'Newest first',
  oldest: 'Oldest first',
  updated_desc: 'Recently updated',
  updated_asc: 'Least recently updated',
};

/** Whether `filters` narrow their scope at all. */
export function hasFilters({ q, type, tag, owner, updatedFrom, updatedTo }: Filters): boolean {
  return Boolean(q || type || tag || owner || updatedFrom || updatedTo);
}

/**
 * Search box on top, below it the scope (which artifacts to show), type, tag and owner filters and the sort order. A search applies once typing pauses,
 * the other filters at once (Enter applies a search at once too); every change goes through
 * `onChange` (which puts it in the URL). With AI, *AI search* replaces the filters with what a
 * description asks for; owner and dates show as removable chips.
 */
export function GalleryFilters({
  filters,
  loading,
  onChange,
}: {
  filters: Filters;
  /** Results for the current filters are on their way. */
  loading: boolean;
  onChange: (filters: Filters) => void;
}) {
  const [text, setText] = useState(filters.q ?? '');
  /** A search typed but not applied yet. */
  const [pending, setPending] = useState(false);
  const [shownQ, setShownQ] = useState(filters.q);
  const [ownerText, setOwnerText] = useState(filters.owner ?? '');
  const [shownOwner, setShownOwner] = useState(filters.owner);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const { data: tags } = useArtifactTags(filters.scope);
  const { data: config } = useAppConfig();
  const smart = config?.features.ai ?? false;

  // The URL's search changed elsewhere (Clear filters, the back button): show it.
  if (filters.q !== shownQ) {
    setShownQ(filters.q);
    if (text.trim() !== (filters.q ?? '')) setText(filters.q ?? '');
  }
  if (filters.owner !== shownOwner) {
    setShownOwner(filters.owner);
    setOwnerText(filters.owner ?? '');
  }
  useEffect(() => () => clearTimeout(timer.current), []);

  /** Applies `changes` with whatever is typed, cancelling a search still waiting to apply. */
  const apply = (changes: Partial<Filters>, typed = text) => {
    clearTimeout(timer.current);
    setPending(false);
    onChange({ ...filters, q: typed.trim() || undefined, ...changes });
  };

  const onType = (value: string) => {
    setText(value);
    setPending(true);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => apply({}, value), SEARCH_DELAY_MS);
  };

  /** Filters from an AI search, replacing the current ones. */
  const applySearch = (found: Filters) => {
    clearTimeout(timer.current);
    setPending(false);
    setText(found.q ?? '');
    onChange(found);
  };

  const active = hasFilters(filters);
  const updated = formatUpdatedRange(filters.updatedFrom, filters.updatedTo);
  const chips = [
    updated ? { label: updated, clear: { updatedFrom: undefined, updatedTo: undefined } } : null,
  ].filter((chip) => chip !== null);
  const tagOptions = tags?.map((item) => item.tag) ?? [];
  // A tag from the URL stays selectable even if it isn't among the most used.
  if (filters.tag && !tagOptions.includes(filters.tag)) tagOptions.unshift(filters.tag);

  /** Applies the owner typed, if it changed. */
  const applyOwner = () => {
    if (ownerText.trim() !== (filters.owner ?? '')) apply({ owner: ownerText.trim() || undefined });
  };

  return (
    <div role="search" className="grid gap-3">
      <div className="flex flex-wrap items-center gap-2">
        <div className="relative min-w-56 flex-1">
          {pending || loading ? (
            <Loader2Icon
              className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 animate-spin text-muted-foreground"
              aria-hidden="true"
            />
          ) : (
            <SearchIcon
              className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground"
              aria-hidden="true"
            />
          )}
          <Input
            type="search"
            aria-label="Search"
            placeholder="Search titles, tags and descriptions"
            className="pl-8"
            value={text}
            onChange={(event) => onType(event.target.value)}
            onKeyDown={(event) => {
              if (event.key !== 'Enter' || event.nativeEvent.isComposing) return;
              event.preventDefault();
              apply({});
            }}
          />
        </div>
        {smart ? <AiSearchDialog scope={filters.scope} onSearch={applySearch} /> : null}
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <NativeSelect
          aria-label="Show"
          value={filters.scope}
          // The tags belong to the scope.
          onChange={(event) =>
            apply({ scope: event.target.value as Filters['scope'], tag: undefined })
          }
        >
          {ARTIFACT_LIST_SCOPES.map((scope) => (
            <option key={scope} value={scope}>
              {SCOPE_LABELS[scope]}
            </option>
          ))}
        </NativeSelect>
        <NativeSelect
          aria-label="Type"
          value={filters.type ?? ''}
          onChange={(event) =>
            apply({ type: (event.target.value || undefined) as Filters['type'] })
          }
        >
          <option value="">All types</option>
          {TYPE_FILTERS.map((type) => (
            <option key={type} value={type}>
              {TYPE_FILTER_LABELS[type]}
            </option>
          ))}
        </NativeSelect>
        <NativeSelect
          aria-label="Tag"
          value={filters.tag ?? ''}
          onChange={(event) => apply({ tag: event.target.value || undefined })}
        >
          <option value="">All tags</option>
          {tagOptions.map((tag) => (
            <option key={tag} value={tag}>
              {tag}
            </option>
          ))}
        </NativeSelect>
        <Input
          type="text"
          aria-label="Owner"
          placeholder="Owner name or email"
          className="w-52"
          value={ownerText}
          onChange={(event) => setOwnerText(event.target.value)}
          onBlur={applyOwner}
          onKeyDown={(event) => {
            if (event.key !== 'Enter' || event.nativeEvent.isComposing) return;
            event.preventDefault();
            applyOwner();
          }}
        />
        <NativeSelect
          aria-label="Sort by"
          value={filters.sort ?? ''}
          onChange={(event) =>
            apply({ sort: (event.target.value || undefined) as Filters['sort'] })
          }
        >
          <option value="">{filters.q ? SORT_LABELS.relevance : SORT_LABELS.updated_desc}</option>
          <option value="newest">{SORT_LABELS.newest}</option>
          <option value="oldest">{SORT_LABELS.oldest}</option>
          {/* Without a search, recently updated is the default above. */}
          {filters.q ? <option value="updated_desc">{SORT_LABELS.updated_desc}</option> : null}
          <option value="updated_asc">{SORT_LABELS.updated_asc}</option>
        </NativeSelect>
        {chips.map(({ label, clear }) => (
          <Button
            key={label}
            variant="secondary"
            size="sm"
            aria-label={`Remove filter: ${label}`}
            onClick={() => apply(clear)}
          >
            {label}
            <XIcon aria-hidden="true" />
          </Button>
        ))}
        {active ? (
          <Button
            variant="ghost"
            onClick={() => {
              clearTimeout(timer.current);
              setPending(false);
              setText('');
              setOwnerText('');
              onChange({ scope: filters.scope, sort: filters.sort });
            }}
          >
            <XIcon aria-hidden="true" />
            Clear filters
          </Button>
        ) : null}
      </div>
    </div>
  );
}
): Promise<SharedArtifactResponse> {
  return apiRequest(sharedPath(token), { schema: sharedArtifactResponseSchema, signal });
}

/** Where a share link's content is, relative to `/api`. */
export function sharedContentPath(token: string): string {
  return `${sharedPath(token)}/content`;
}

/** Other users whose email or name starts with `query` (3+ characters), at most five. */
export async function searchUsers(query: string, signal?: AbortSignal): Promise<UserSummary[]> {
  const params = new URLSearchParams({ q: query });
  return (await apiRequest(`/users/search?${params}`, { schema: userSearchResponseSchema, signal }))
    .items;
}
