import type { ArtifactListScope } from '@artifact-hub/shared';
import { useId, useState } from 'react';
import { Input } from '@/components/ui/input.tsx';
import { useArtifactTags } from './use-artifacts.ts';

/**
 * Finds tags to filter by: suggests a few of the scope's tags, the most used first, and searches
 * them on the server as you type. Picking one (a suggestion fills in its tag) hands it over and
 * clears the box, so several can be picked one after another.
 */
export function TagPicker({
  scope,
  selected,
  onPick,
}: {
  scope: ArtifactListScope;
  /** Tags already picked, which aren't suggested again. */
  selected: readonly string[];
  onPick: (tag: string) => void;
}) {
  const [draft, setDraft] = useState('');
  const { data: tags } = useArtifactTags(scope, draft);
  const listId = useId();
  const suggestions = tags?.filter((item) => !selected.includes(item.tag)) ?? [];

  const onChange = (value: string) => {
    const picked = suggestions.find((item) => item.tag === value.trim().toLowerCase());
    if (picked) {
      setDraft('');
      onPick(picked.tag);
    } else {
      setDraft(value);
    }
  };

  return (
    <>
      <Input
        type="text"
        aria-label="Tags"
        placeholder="Filter by tag"
        className="w-40"
        autoComplete="off"
        list={listId}
        value={draft}
        onChange={(event) => onChange(event.target.value)}
      />
      <datalist id={listId}>
        {suggestions.map((item) => (
          <option key={item.tag} value={item.tag}>
            {item.count} {item.count === 1 ? 'artifact' : 'artifacts'}
          </option>
        ))}
      </datalist>
    </>
  );
}
