/** Below this width the filters are in a dialog, opened by an icon. Tailwind's `sm`. */
const WIDE_SCREEN = '(min-width: 640px)';

/** How many filters other than the search are set, for the badge on the dialog's icon. */
function countActiveFilters({
  scope,
  type,
  tag,
  owner,
  ownerId,
  updatedFrom,
  updatedTo,
  sort,
}: Filters): number {
  return [
    scope !== 'mine',
    type,
    tag?.length,
    owner || ownerId,
    updatedFrom || updatedTo,
    sort,
  ].filter(Boolean).length;
}
        {wide ? null : (
